(() => {
  const CONFIG = {
    rootAttr: 'data-bunny-background-init',
    toggleAttr: 'data-sound-toggle',
    cursorAttr: 'data-sound-cursor',
    labelMuted: 'sound on',
    labelUnmuted: 'sound off',
  };

  const cursor = document.querySelector(`[${CONFIG.cursorAttr}]`);

  let px = 0,
    py = 0,
    moved = false;
  window.addEventListener('pointermove', (e) => {
    px = e.clientX;
    py = e.clientY;
    moved = true;
  }, { passive: true });

  document.querySelectorAll(`[${CONFIG.toggleAttr}]`).forEach((toggle) => {
    const root = toggle.closest(`[${CONFIG.rootAttr}]`);
    if (!root) return;

    const label = () => {
      const video = root.querySelector('video');
      if (!video) return;
      const muted = video.muted ? 'true' : 'false';
      root.setAttribute('data-player-muted', muted);
      toggle.setAttribute('data-cursor-text', video.muted ? CONFIG.labelMuted : CONFIG
        .labelUnmuted);
      if (cursor) cursor.setAttribute('data-player-muted', muted);
    };

    // volumechange doesn't bubble — capture on root survives video node swaps
    root.addEventListener('volumechange', () => {
      label();
      if (moved) window.dispatchEvent(new PointerEvent('pointermove', {
        clientX: px,
        clientY: py
      }));
    }, true);

    label();
  });
})();


